var data = $input.item.json.body || $input.item.json;
var date = data.date || new Date().toISOString().split('T')[0];
var sources = (data.news_headlines || []).map(function(h) { return h.url; }).filter(Boolean);
var markets = (data.top_markets || []).map(function(m) { return m.symbol + ': $' + (m.price || 0).toLocaleString() + ' (' + (m.change_24h > 0 ? '+' : '') + (m.change_24h || 0).toFixed(2) + '% 24h)'; }).join(', ');
var trending = (data.trending_coins || []).map(function(c) { return c.name + ' (' + c.symbol + ')'; }).join(', ');
var reddit = (data.reddit_top_posts || []).slice(0,5).map(function(p) { return p.title; }).join('; ');
var headlines = (data.news_headlines || []).slice(0,8).map(function(h) { return h.title; }).join('; ');
var mcap = (data.market_summary && data.market_summary.total_market_cap_usd) ? '$' + (data.market_summary.total_market_cap_usd / 1e12).toFixed(2) + 'T' : 'N/A';
var btcDom = (data.market_summary && data.market_summary.btc_dominance) ? data.market_summary.btc_dominance.toFixed(1) + '%' : 'N/A';
var chg = (data.market_summary && data.market_summary.market_cap_change_24h_pct) ? data.market_summary.market_cap_change_24h_pct.toFixed(2) + '%' : 'N/A';
var prompt = 'Date: ' + date + '. Total market cap: ' + mcap + '. BTC dominance: ' + btcDom + '. 24h change: ' + chg + '. Top assets: ' + markets + '. Trending: ' + trending + '. Reddit discussions: ' + reddit + '. Headlines: ' + headlines + '. Write the daily brief for ' + date + '.';
var sys = 'You are Alpha Research, the voice of AlphaForgeAI. You are a battle-tested crypto market analyst who was mining Bitcoin before Mt. Gox went down. You are a long-term Bitcoin Maximalist. BTC is the reserve asset. It is never going to zero. If a Bitcoin death article or crypto obituary appears in the provided headlines, you may discredit it with facts or a dry remark -- but only if it is actually in the data. Do not bring it up otherwise. Your audience is traders -- from beginners learning the ropes to experienced participants. Be accessible but substantive. Explain jargon briefly when you use it. Take directional positions. State clearly early in the post whether the overall market is Bullish, Bearish, or Neutral -- and tell the story of why. Cover: BTC and ETH always. Macro (Fed, CPI, DXY) always. Regulatory news always. Signal assets when relevant: BTC, ETH, SOL, XRP, AVAX, DOT, NEAR, UNI, AAVE, COMP, SNX, CRV, LTC, BCH, ARB, OP, SUI, APT, INJ, POL, FIL, SHIB, PEPE, FLOKI, BONK, WIF. Top memecoins and top 25 altcoins by market cap when they have meaningful moves. Use ONLY the data provided -- do not invent prices, percentages, or news events. No financial advice. No buy/sell recommendations. No price targets. Length 500-800 words. Write in markdown with ## section headers. Sections: ## Market Overview (state Bullish/Bearish/Neutral here), ## What Is Moving, ## Key Stories, ## Closing Note. End every post with: This post is for informational purposes only and does not constitute financial advice. After that disclaimer, on its own new line, output exactly: TAGS: followed by 3-6 comma-separated lowercase kebab-case tags specific to what this post actually covers today (e.g. btc-dominance, fed-rate-cut, solana-rally, defi-tvl, regulatory-news). Do not use generic tags like crypto, market, or bitcoin unless BTC price action is specifically the lead story today.';
var body = JSON.stringify({ model: 'claude-sonnet-4-5', max_tokens: 2000, system: sys, messages: [{ role: 'user', content: prompt }] });
return [{ json: { date: date, sources: sources, claude_body: body } }];

const claudeResp = $input.item.json;
let content = claudeResp.content?.[0]?.text || '';
const prev = $('Build Claude Prompt').item.json;
const date = prev.date;

// Extract Claude's explicit topical tags (TAGS: tag-one, tag-two, ...) and strip the line from displayed content
const tagsMatch = content.match(/TAGS:\s*(.+)/i);
let tags = tagsMatch
  ? tagsMatch[1].split(',').map(t => t.trim().toLowerCase().replace(/[^a-z0-9-]/g, '')).filter(Boolean).slice(0, 6)
  : [];
if (tags.length === 0) tags = ['daily-brief', 'market'];
content = content.replace(/\n?TAGS:\s*.+/i, '').trim();

const lines = content.split('\n').filter(l => l.trim());
const firstLine = lines[0] || '';
const title = firstLine.startsWith('#')
  ? firstLine.replace(/^#+\s*/, '').trim()
  : `Crypto Daily Brief - ${date}`;

const slug = 'crypto-daily-brief-' + date;

const summary = lines.find(l => !l.startsWith('#') && l.length > 50) || 'Daily crypto market analysis.';

const assetRegex = /\b(BTC|ETH|SOL|XRP|BNB|AVAX|DOGE|ADA|DOT|MATIC|LINK|UNI|AAVE|SNX|CRV|COMP|INJ|OP|ARB|SUI|APT|NEAR|FIL|LTC|BCH|SHIB|PEPE|FLOKI|BONK|WIF|POL)\b/g;
const assets = [...new Set(content.match(assetRegex) || ['BTC'])];

return [{
  json: {
    schema_version: 1,
    posts: [{
      slug,
      title,
      published_at: new Date().toISOString(),
      summary: summary.slice(0, 200),
      content,
      sources: prev.sources || [],
      assets,
      tags,
      author: 'Alpha Research'
    }]
  }
}];

